<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login(); $pdo=db();
if(!table_exists($pdo,'payments')) redirect('upgrade_phase4.php');
$msg=flash('success');$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=post_int('client_id');$invoice=post_int('invoice_id')?:null;$amount=(float)($_POST['amount']??0);if($client&&$amount>0){try{$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO payments(client_id,invoice_id,payment_reference,payment_date,amount,method,notes,created_by) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$client,$invoice,post_string('payment_reference')?:null,post_string('payment_date')?:date('Y-m-d'),$amount,post_string('method','bank_transfer'),post_string('notes')?:null,current_user()['id']]);$pid=(int)$pdo->lastInsertId();if($invoice){$st=$pdo->prepare('UPDATE invoices SET paid_amount=LEAST(total_amount,paid_amount+?), status=CASE WHEN paid_amount+?>=total_amount THEN "paid" WHEN paid_amount+?>0 THEN "partial" ELSE status END WHERE id=? AND client_id=?');$st->execute([$amount,$amount,$amount,$invoice,$client]);} $pdo->commit();activity($pdo,'create','payments',$pid,'Payment recorded: '.$amount);flash('success','Payment recorded and invoice balance updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[SPS PAYMENTS] '.$e->getMessage());flash('success','Payment could not be recorded.');}}else{flash('success','Client and positive payment amount are required.');}redirect('payments.php');}
$clients=$pdo->query("SELECT id,first_name,last_name FROM clients WHERE deleted_at IS NULL ORDER BY last_name")->fetchAll();
$invoices=$pdo->query("SELECT i.id,i.invoice_number,i.client_id,i.total_amount,i.paid_amount,CONCAT(c.first_name,' ',c.last_name) client_name FROM invoices i JOIN clients c ON c.id=i.client_id WHERE i.status NOT IN ('paid','cancelled') ORDER BY i.id DESC")->fetchAll();
$rows=$pdo->query("SELECT p.*,CONCAT(c.first_name,' ',c.last_name) client_name,i.invoice_number FROM payments p JOIN clients c ON c.id=p.client_id LEFT JOIN invoices i ON i.id=p.invoice_id ORDER BY p.id DESC LIMIT 200")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payments · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:11px 14px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Payments</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="grid"><div class="card"><h2>Record Payment</h2><form method="post"><?=csrf_field()?><div class="field"><label>Client</label><select name="client_id" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Invoice</label><select name="invoice_id"><option value="">No invoice</option><?php foreach($invoices as $i):?><option value="<?=$i['id']?>"><?=e($i['invoice_number'].' · '.$i['client_name'].' · $'.number_format($i['total_amount']-$i['paid_amount'],2))?></option><?php endforeach;?></select></div><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Date</label><input name="payment_date" type="date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Method</label><select name="method"><option>bank_transfer</option><option>cash</option><option>card</option><option>check</option><option>other</option></select></div><div class="field"><label>Reference</label><input name="payment_reference"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><button class="btn">Record Payment</button></form></div><div class="card"><h2>Payment History</h2><table class="table"><tr><th>Date</th><th>Client</th><th>Invoice</th><th>Method</th><th>Amount</th><th>Reference</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['payment_date'])?></td><td><?=e($r['client_name'])?></td><td><?=e($r['invoice_number']?:'—')?></td><td><?=e($r['method'])?></td><td>$<?=money($r['amount'])?></td><td><?=e($r['payment_reference']?:'—')?></td></tr><?php endforeach;?></table><?php if(!$rows):?><p>No payments yet.</p><?php endif;?></div></div></main></body></html>
